def free_frame_answer_map(rows, operation):
    out = {}
    for row in rows:
        if not isinstance(row, dict) or row.get('operation') != operation:
            continue
        qid = row.get('id', '')
        parts = qid.rsplit('__', 1)
        if len(parts) == 2 and parts[1]:
            out[parts[1]] = row
    return out

def free_frame_condition(raw):
    text = low(raw)
    items = []
    if has_any(text, ['need to know', 'need-to-know', 'bona fide need']):
        items.append(['need_to_know', raw])
    if has_any(text, ['extent necessary', 'strictly necessary', 'reasonably necessary', 'disclosure is necessary']):
        items.append(['extent_necessary', raw])
    if has_any(text, ['obligated to protect', 'obliged by their contracts', 'bound by obligations', 'duty of confidentiality', 'treat such confidential information', 'terms no less protective', 'terms no less stringent', 'contracts of employment or services']):
        items.append(['confidentiality_bound', raw])
    return make_and(items)

def free_frame_is_disclosure_row(row, focus_keys):
    if not isinstance(row, dict):
        return False
    term = row.get('term')
    if not isinstance(term, list) or not term:
        return False
    if term[0] not in ('permission', 'prohibition', 'acq_disclosure_v3'):
        return False
    for uid in row.get('support_ids', []):
        if str(uid) in focus_keys:
            return True
    return False

def free_compose_reviewed_employee_frames(inputs, statements):
    rows = pb_rows(inputs.get('semantic_answers', []))
    effects = free_frame_answer_map(rows, 'employee_disclosure_focus_effect_v3')
    owners = free_frame_answer_map(rows, 'employee_permission_owner_v3')
    spans = {}
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans[str(span.get('id'))] = span
    unresolved = []
    for key, effect in effects.items():
        choice = effect.get('choice')
        if choice not in ('operative_employee_permission', 'employee_permission_exception'):
            continue
        owner_answer = owners.get(key)
        owner_choice = owner_answer.get('choice') if isinstance(owner_answer, dict) else None
        recipient = None
        direct = ['employees_of', ['receiving_party']]
        affiliated = ['employees_of', ['controlled_entities_of', ['receiving_party']]]
        if owner_choice == 'recipient_owned_employees':
            recipient = direct
        elif owner_choice == 'affiliate_owned_employees':
            recipient = affiliated
        elif owner_choice == 'recipient_and_affiliate_employees':
            recipient = ['participant_union', direct, affiliated]
        if recipient is None:
            unresolved.append('reviewed employee permission owner remains outside the composable owner classes for focus ' + key)
            continue
        span = spans.get(key)
        if not isinstance(span, dict):
            unresolved.append('reviewed employee permission focus is unavailable for ' + key)
            continue
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        actor = actor_for(low(raw))
        permission = ['permission', actor, ['disclose', ['confidential_information'], recipient], free_frame_condition(raw)]
        support = [span.get('id')]
        if choice == 'operative_employee_permission':
            add_statement(statements, permission, support)
        else:
            add_statement(statements, ['prohibition', actor, ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], ['exception_set', ['permission_exception', permission]]], support)
    return unresolved

def apply(inputs, premises):
    source_output = inputs.get('source_output', {})
    rows = pb_rows(inputs.get('semantic_answers', []))
    effects = free_frame_answer_map(rows, 'employee_disclosure_focus_effect_v3')
    focus_keys = set(effects.keys())
    statements = []
    unresolved = []
    complete = False
    unreviewed_rows = []
    if isinstance(source_output, dict):
        complete = bool(source_output.get('complete', False))
        for row in source_output.get('statements', []):
            if not isinstance(row, dict) or not isinstance(row.get('term'), list):
                continue
            if free_frame_is_disclosure_row(row, focus_keys):
                continue
            copied = {'term': row.get('term'), 'support_ids': list(row.get('support_ids', []))}
            statements.append(copied)
            unreviewed_rows.append(copied)
        for item in source_output.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    unreviewed_source = {'statements': unreviewed_rows, 'unresolved': [], 'complete': complete}
    free_compose_acquired_disclosures(unreviewed_source, statements)
    free_compose_acquired_policy(source_output, statements)
    unresolved.extend(free_compose_reviewed_employee_frames(inputs, statements))
    spans = []
    all_ids = []
    elliptical = False
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
            all_ids.append(span.get('id'))
    i = 0
    while i < len(spans):
        span = spans[i]
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        if free_elliptical_permission(raw, uid, statements):
            elliptical = True
        free_add_disposal_repairs(raw, uid, statements)
        free_explicit_disclosure_repairs(raw, free_clause_context(spans, i), uid, statements)
        i += 1
    if not free_disposal_present(spans):
        add_statement(statements, ['complete_source_no_disposal_obligation'], all_ids)
    if not free_post_disposal_retention_present(spans):
        add_statement(statements, ['complete_source_no_retention_effect'], all_ids)
    if not free_internal_permission_present(spans) and not elliptical and not pb_has_root(statements, 'permission'):
        add_statement(statements, ['complete_source_no_disclosure_permission'], all_ids)
    return {'statements': statements, 'complete': complete and len(unique(unresolved)) == 0, 'unresolved': unique(unresolved)}

