def apply(inputs, premises):
    spans = []
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
    rows = pa_rows(inputs.get('semantic_answers', []))
    source_output = inputs.get('source_output', {})
    supported = set()
    if isinstance(source_output, dict):
        for row in source_output.get('statements', []):
            if not isinstance(row, dict):
                continue
            term = row.get('term')
            relevant = term_has_constructor(term, 'permission') or term_has_constructor(term, 'prohibition') or term_has_constructor(term, 'acq_disclosure_v3') or term_has_constructor(term, 'define_representative')
            if relevant:
                for uid in row.get('support_ids', []):
                    supported.add(uid)
    candidates = []
    i = 0
    while i < len(spans):
        uid = spans[i].get('id')
        text = pa_low(spans[i].get('text', ''))
        people = pa_any(text, ['employee', 'staff', 'personnel'])
        disclosure = pa_any(text, ['disclos', 'restrict access', 'make accessible', 'reveal', 'divulge', 'share'])
        definition = pa_any(text, ['means an entity', 'shall mean', 'means directors', 'means officers', 'representative']) and pa_any(text, ['affiliate', 'employee', 'representative', 'control'])
        operative = pa_any(text, ['may ', 'shall ', 'will ', 'not to ', 'except ', 'restrict '])
        if (people and disclosure and (operative or uid in supported)) or definition or (uid in supported and (people or 'affiliate' in text)):
            candidates.append(i)
        i += 1
    queries = []
    for pos in candidates:
        uid = spans[pos].get('id')
        start = max(0, pos - 2)
        unit_ids = []
        j = start
        while j <= pos:
            unit_ids.append(spans[j].get('id'))
            j += 1
        effect_id = 'employee_frame_effect__' + str(uid)
        effect = pa_answer(rows, effect_id)
        if effect is None:
            queries.append({'id': effect_id, 'operation': 'employee_disclosure_focus_effect_v3', 'unit_ids': unit_ids})
        elif effect.get('choice') in ('operative_employee_permission', 'employee_permission_exception'):
            owner_id = 'employee_frame_owner__' + str(uid)
            if pa_answer(rows, owner_id) is None:
                queries.append({'id': owner_id, 'operation': 'employee_permission_owner_v3', 'unit_ids': unit_ids})
    return {'queries': queries}

